import { createContext, useState } from "react";
import { createBrowserRouter, RouterProvider } from "react-router-dom";
import Dashboard from "./Pages/Dashboard";
import Header from "./Components/Header";
import Sidebar from "./Components/Sidebar";
import * as React from 'react';

import toast, { Toaster } from 'react-hot-toast';
import { fetchDataFromApi } from "./utils/api";

export const MyContext = createContext();
const alertBox = (msg, type) => {
  if (type === "success") {
    toast.success(msg)
  }
  if (type === "error") {
    toast.error(msg)
  }
}


export default function App() {

  React.useEffect(() => {
    fetchDataFromApi("/api/category").then((res) => {
      if (res?.error === false) {
        setcatData(res?.data);
      }
    });
  }, []);







  const values = {
    Bdatafunction,
    sizeDatagot, getSizetData, weightDatagot, getWeighttData, setimbData, imbData, Datagotim,setDataB,dataB,
    setisSidebarOpen, setOpenFullscreemProduct, userDetailsdata, setuserDetailsdata, setcatData, catData,
    isSidebarOpen, isLogin, setisLogin, openFullscreemProduct, alertBox, ramdataShow, setramdataShow, apiFunctionToRamGETfetch
  };


  const router = createBrowserRouter([
    {
      path: "/",
      element: (
        <section className="main">
          <Header />
          <div className="contentMain flex">
            <div className={`overflow-hidden sidebarWrapper w-0 opacity-0 pointer-events-none transition-all`}>
              <Sidebar />
            </div>
            <div
              className={`contentRight py-4 px-5 w-[100%]" 
                } transition-all`}
              style={{
                background: "radial-gradient(black, transparent)",
              }}
            >
              <Dashboard />
            </div>
          </div>
        </section>
      ),
    },


  ]);

  return (
    <>
      <MyContext.Provider value={values}>
        <RouterProvider router={router} />





















      </MyContext.Provider>
      <Toaster /></>
  );
}
